package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TypeFactory.constructParametricType(Class<?> parametrized, Class<?>... parameterClasses)
 */
public class TypeFactory_constructParametricType_TriageGen1Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testConstructParametricType_SingleParameter() {
        // Test List<String>
        JavaType result = typeFactory.constructParametricType(List.class, String.class);

        Assert.assertNotNull("Resulting JavaType should not be null", result);
        Assert.assertEquals("Raw class should be List", List.class, result.getRawClass());
        Assert.assertEquals("Should have 1 parameter type", 1, result.getTypeParameters().length);
        Assert.assertEquals("Parameter type should be String", String.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructParametricType_MultipleParameters() {
        // Test Map<String, Integer>
        JavaType result = typeFactory.constructParametricType(Map.class, String.class, Integer.class);

        Assert.assertNotNull("Resulting JavaType should not be null", result);
        Assert.assertEquals("Raw class should be Map", Map.class, result.getRawClass());
        Assert.assertEquals("Should have 2 parameter types", 2, result.getTypeParameters().length);
        Assert.assertEquals("First parameter type should be String", String.class, result.getTypeParameters()[0].getRawClass());
        Assert.assertEquals("Second parameter type should be Integer", Integer.class, result.getTypeParameters()[1].getRawClass());
    }

    @Test
    public void testConstructParametricType_NoParameters() {
        // Test a non-parametric class (though the method is designed for parametric ones)
        // This tests the loop behavior when len == 0
        JavaType result = typeFactory.constructParametricType(String.class);

        Assert.assertNotNull("Resulting JavaType should not be null", result);
        Assert.assertEquals("Raw class should be String", String.class, result.getRawClass());
        Assert.assertEquals("Should have 0 parameter types", 0, result.getTypeParameters().length);
    }

    @Test
    public void testConstructParametricType_WithPrimitives() {
        // Test List<Integer> (using wrapper) and List<int[]> (using array)
        // Note: parameterClasses accepts Class<?> which includes primitives
        JavaType result = typeFactory.constructParametricType(List.class, int[].class);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(int[].class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructParametricType_NestedParametric() {
        // Test List<List<String>>
        JavaType innerType = typeFactory.constructParametricType(List.class, String.class);
        JavaType outerType = typeFactory.constructParametricType(List.class, innerType.getRawClass()); 

        // However, the method signature provided takes Class<?>... parameterClasses.
        // If we pass the inner Type class, it might not behave as expected if it's not a simple Class.
        // But the method implementation calls _fromClass(null, parameterClasses[i], null).
        // _fromClass expects a Class object.

        JavaType result = typeFactory.constructParametricType(List.class, List.class);
        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(List.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructParametricType_ComplexClasses() {
        // Test with an anonymous or complex class
        class MyComplexClass<T, U> {}

        JavaType result = typeFactory.constructParametricType(MyComplexClass.class, String.class, Double.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(MyComplexClass.class, result.getRawClass());
        Assert.assertEquals(2, result.getTypeParameters().length);
        Assert.assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
        Assert.assertEquals(Double.class, result.getTypeParameters()[1].getRawClass());
    }
}
